        return env.step(cmd)

    g = goal.lower().rstrip('.')

    # Parse goal
    relation = None
    target = None
    anchor = None

    if 'look at' in g:
        relation = 'look'
        mm = re.search(r'look at (?:the )?(.+?)(?: (?:under|on|in|with) the (.+))?$', g)
        if mm:
            target = mm.group(1).strip()
            anchor = mm.group(2)
    else:
        for rel in ['put', 'place', 'move']:
            if g.startswith(rel + ' '):
                rest = g[len(rel)+1:]
                mm = re.match(r'(.+?) (?:in|on|under|into|to|at) (?:the )?(.+)$', rest)
                if mm:
                    target = mm.group(1).strip()
                    anchor = mm.group(2).strip()
                    relation = 'move'
                break

    def norm(s):
        s = s.strip().lower()
        s = re.sub(r'^(a|an|the)\s+', '', s)
        return s

    def find_ids(text):
        # return list of full object ids like "book 1"
        return [m.group(0) for m in re.finditer(r'([a-z]+(?:\s[a-z]+)?)\s+(\d+)', text, re.I)]

    def is_match(obj_id, want):
        w = norm(want)
        o = norm(obj_id)
        # strip trailing numbers for name comparison
        oname = re.sub(r'\s+\d+$', '', o)
        return oname == w or w in oname or oname in w

    # Parse room description for receptacles
    obs = env.observation
    receptacles = []
    for m in re.finditer(r'\b(a|an|the)\s+([a-z]+(?:\s[a-z]+)?)\s+(\d+)', obs, re.I):
        name = m.group(2).lower()
        if any(w in name for w in ['shelf','drawer','fridge','refrigerator','desk','table','bed','laundryhamper','garbagecan','cabinet','counter','sink','box','chest','closet','safe']):
            full = m.group(0)
            # normalize to "name num"
            num = m.group(3)
            receptacles.append((name, num, f'{name} {num}'))

    current_loc = None
    steps = [0]

    def step(cmd):
        steps[0] += 1
        return act(cmd)

    def go_to(rec):
        r = step(f'go to {rec}')
        return r

    def take(obj):
        r = step(f'take {obj} from {current_loc}')
        return r

    def use(obj):
        r = step(f'use {obj}')
        return r

    # Search for object by name across receptacles. Returns (obj_id, location) or None.
    def find_object(want, do_take=False):
        nonlocal current_loc
        # Check current location first
        if current_loc:
            ids = find_ids(env.observation)
            for o in ids:
                if is_match(o, want):
                    if do_take:
                        take(o)
                    return o
        for name, num, rec_id in receptacles:
            current_loc = rec_id
            r = go_to(rec_id)
            if 'arrive' in r.lower() or 'see' in r.lower() or 'on the' in r.lower():
                ids = find_ids(env.observation)
                for o in ids:
                    if is_match(o, want):
                        if do_take:
                            take(o)
                        return o
        return None

    # Handle look relation
    if relation == 'look':
        # Find target object (e.g., book)
        obj = find_object(target, do_take=True)
        # Find anchor (e.g., desklamp)
        lamp = find_object(anchor, do_take=False)
        if lamp:
            use(lamp)
        step('look')
        return

    # Handle move relation
    if relation == 'move':
        obj = find_object(target, do_take=True)
        anchor_n = norm(anchor)
        dest = None
        for name, num, rec_id in receptacles:
            if name == anchor_n or anchor_n in name or name in anchor_n:
                dest = rec_id
                break
        if dest:
            current_loc = dest
            go_to(dest)
            if obj:
                step(f'put {obj} in {dest}')
            else:
                step(f'put {target} in {dest}')
        return

    # Fallback
    step('look')
